import React, { useState, useEffect } from "react";
import "./Voting.css";

const Voting = ({ userData, onVoteComplete }) => {
  const [candidates, setCandidates] = useState([]);
  const [selectedCandidate, setSelectedCandidate] = useState(null);
  const [loading, setLoading] = useState(false);
  const [voted, setVoted] = useState(false);

  useEffect(() => {
    fetchCandidates();
    checkVoteStatus();
  }, []);

  const fetchCandidates = async () => {
    try {
      const response = await fetch("http://localhost:5000/api/candidates");
      const data = await response.json();
      if (data.success) setCandidates(data.candidates);
    } catch (error) {
      console.error("Error fetching candidates:", error);
    }
  };

  const checkVoteStatus = async () => {
    // Check if user has already voted
    if (userData?.walletAddress) {
      try {
        const response = await fetch(
          `http://localhost:5000/api/check-vote/${userData.walletAddress}`
        );
        const data = await response.json();
        if (data.hasVoted) setVoted(true);
      } catch (error) {
        console.error("Error checking vote status:", error);
      }
    }
  };

  const castVote = async () => {
    if (!selectedCandidate) {
      alert("Please select a candidate");
      return;
    }

    setLoading(true);
    try {
      const response = await fetch("http://localhost:5000/api/cast-vote", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          candidateId: selectedCandidate.id,
          walletAddress: userData.walletAddress,
        }),
      });

      const data = await response.json();
      if (data.success) {
        setVoted(true);
        onVoteComplete();
        alert("✅ Vote cast successfully on blockchain!");
      } else {
        alert("❌ " + data.message);
      }
    } catch (error) {
      console.error("Voting error:", error);
      alert("❌ Failed to cast vote");
    } finally {
      setLoading(false);
    }
  };

  if (voted) {
    return (
      <div className="voting-complete">
        <div className="success-icon">✅</div>
        <h2>Thank You for Voting!</h2>
        <p>Your vote has been successfully recorded on the blockchain.</p>
        <button
          onClick={() => window.location.reload()}
          className="back-button"
        >
          Back to Home
        </button>
      </div>
    );
  }

  return (
    <div className="voting-container">
      <h2>🗳️ Cast Your Vote</h2>
      <p>Select your preferred candidate:</p>

      <div className="candidates-list">
        {candidates.map((candidate) => (
          <div
            key={candidate.id}
            className={`candidate-card ${
              selectedCandidate?.id === candidate.id ? "selected" : ""
            }`}
            onClick={() => setSelectedCandidate(candidate)}
          >
            <div className="candidate-info">
              <h3>{candidate.name}</h3>
              <p className="party">{candidate.party}</p>
              {candidate.symbol && (
                <p className="symbol">Symbol: {candidate.symbol}</p>
              )}
              {candidate.description && (
                <p className="description">{candidate.description}</p>
              )}
            </div>
            <div className="select-indicator">
              {selectedCandidate?.id === candidate.id ? "✓" : "○"}
            </div>
          </div>
        ))}
      </div>

      {selectedCandidate && (
        <div className="vote-confirmation">
          <h3>Confirm Your Vote</h3>
          <p>
            You are voting for: <strong>{selectedCandidate.name}</strong>
          </p>
          <button
            onClick={castVote}
            disabled={loading}
            className="cast-vote-btn"
          >
            {loading ? "Casting Vote..." : "🗳️ Cast Vote"}
          </button>
        </div>
      )}
    </div>
  );
};

export default Voting;
